 public sealed class VanArt:MonoBehaviour {
  public VehicleController Motor;readonly List<Transform> wheels=new();readonly List<Renderer> paint=new();Renderer[] tails;int lastStyle=-1,lastVehicle=-1;
  static readonly Color Navy=new(.025f,.075f,.13f),Orange=new(1,.32f,.045f);
  public void Build(){var white=MeshArt.Mat("VanPearl",new(.95f,.96f,.94f));var navy=MeshArt.Mat("VanNavy",Navy);var orange=MeshArt.Mat("VanOrange",Orange);var glass=MeshArt.Mat("VanGlass",new(.10f,.28f,.37f));glass.SetFloat("_Metallic",.55f);glass.SetFloat("_Glossiness",.9f);var metal=MeshArt.Mat("VanChrome",new(.64f,.7f,.74f));metal.SetFloat("_Metallic",.8f);metal.SetFloat("_Glossiness",.8f);var tyre=MeshArt.Mat("VanTyre",new(.035f,.04f,.045f));
   var shell=Loft(transform,"Bevelled service body",new[]{-.0f, .22f,1.62f,1.96f},new[]{.94f,1.06f,1.06f,.91f},-2.18f,.83f,white);shell.transform.localPosition=Vector3.up*.45f;
   MeshArt.Box(transform,"Underbody",new(0,.42f,0),new(2.14f,.32f,4.46f),navy);MeshArt.Box(transform,"Front hood",new(0,.89f,1.55f),new(2.08f,.72f,1.25f),white);
   var cab=Loft(transform,"Sloped cab",new[]{1.21f,1.67f,2.08f},new[]{1.02f,.98f,.87f},.52f,1.82f,white);var cabMesh=cab.GetComponent<MeshFilter>().sharedMesh;var cabVertices=cabMesh.vertices;for(int i=0;i<cabVertices.Length;i++)if(cabVertices[i].z>1.69f)cabVertices[i].z=2.55f-cabVertices[i].y*.54f;cabMesh.vertices=cabVertices;cabMesh.RecalculateNormals();cabMesh.RecalculateBounds();MeshArt.Box(transform,"Windshield",new(0,1.7f,1.65f),new(1.79f,.65f,.035f),glass).transform.localRotation=Quaternion.Euler(-28.4f,0,0);
   foreach(int side in new[]{-1,1}){MeshArt.Box(transform,"Side cab glass",new(side*1.022f,1.72f,1.05f),new(.025f,.61f,1.06f),glass);MeshArt.Box(transform,"Sliding door rail",new(side*1.07f,1.22f,-.7f),new(.025f,.025f,2.25f),metal);MeshArt.Box(transform,"Cargo door seam",new(side*1.073f,1.33f,.45f),new(.02f,1.55f,.018f),navy);MeshArt.Box(transform,"Door handle",new(side*1.09f,1.2f,.22f),new(.04f,.075f,.24f),navy);MeshArt.Box(transform,"Mirror arm",new(side*1.14f,1.56f,1.68f),new(.26f,.06f,.08f),navy);MeshArt.Box(transform,"Mirror housing",new(side*1.28f,1.57f,1.67f),new(.15f,.23f,.23f),navy);MeshArt.Box(transform,"Mirror lens",new(side*1.29f,1.57f,1.54f),new(.12f,.19f,.012f),metal);var band=MeshArt.Box(transform,"Orange service band",new(side*1.075f,.72f,-.36f),new(.018f,.41f,3.28f),orange);paint.Add(band.GetComponent<Renderer>());MeshArt.Box(transform,"Roof rack rail",new(side*.81f,2.5f,-.72f),new(.08f,.12f,2.66f),metal);MeshArt.Box(transform,"Ladder rail",new(side*.32f,2.63f,-.75f),new(.075f,.09f,2.86f),metal);}
   for(int i=0;i<10;i++)MeshArt.Box(transform,"Ladder rung",new(0,2.63f,-2.0f+i*.27f),new(.64f,.075f,.055f),metal);
   for(int i=0;i<3;i++)MeshArt.Box(transform,"Rack clamp",new(0,2.42f,-1.7f+i*.9f),new(1.7f,.1f,.1f),navy);
   MeshArt.Box(transform,"Rear split seam",new(0,1.43f,-2.199f),new(.025f,1.78f,.02f),navy);MeshArt.Box(transform,"Rear window left",new(-.47f,1.99f,-2.205f),new(.71f,.38f,.014f),glass);MeshArt.Box(transform,"Rear window right",new(.47f,1.99f,-2.205f),new(.71f,.38f,.014f),glass);MeshArt.Box(transform,"Rear bumper",new(0,.42f,-2.29f),new(2.17f,.22f,.24f),navy);MeshArt.Box(transform,"Front bumper",new(0,.42f,2.2f),new(2.17f,.22f,.18f),navy);MeshArt.Box(transform,"Grille",new(0,.94f,2.18f),new(.94f,.29f,.035f),navy);for(int i=0;i<5;i++)MeshArt.Box(transform,"Grille slat",new(0,.85f+i*.047f,2.205f),new(.84f,.017f,.02f),metal);
   var lights=new List<Renderer>();foreach(int side in new[]{-1,1}){MeshArt.Box(transform,"Headlight",new(side*.78f,1.0f,2.19f),new(.48f,.22f,.035f),MeshArt.Mat("VanHeadlamp",new(1,.96f,.78f),-1,true));var tail=MeshArt.Box(transform,"Rear tail lamp",new(side*.975f,1.12f,-2.225f),new(.12f,.6f,.038f),MeshArt.Mat("VanTail",new(.65f,.035f,.025f),-1,true));lights.Add(tail.GetComponent<Renderer>());MeshArt.Box(transform,"Rear indicator",new(side*.975f,.86f,-2.232f),new(.11f,.14f,.04f),orange);}
   tails=lights.ToArray();MeshArt.Box(transform,"Rear number plate",new(0,.62f,-2.225f),new(.78f,.18f,.03f),white);Text(transform,"REPAIR",new(0,.64f,-2.251f),.095f,Navy,Quaternion.identity);
