  public void Apply(int style,int vehicle){if(lastStyle==style&&lastVehicle==vehicle)return;lastStyle=style;lastVehicle=vehicle;Color[] colors={Orange,new(.08f,.64f,.82f),new(.24f,.75f,.38f),new(.66f,.3f,.94f),new(1,.73f,.1f),new(.16f,.77f,1),new(.35f,.95f,.64f),new(.89f,.30f,.67f)};var mat=MeshArt.Mat("VanPaint"+style,colors[Mathf.Clamp(style,0,7)]);foreach(var r in paint)r.sharedMaterial=mat;transform.localScale=new Vector3(1,vehicle==1?1.10f:1,vehicle==1?1.06f:1);}
  void Update(){if(Motor==null)return;float spin=Vector3.Dot(Motor.GetComponent<Rigidbody>().linearVelocity,Motor.transform.forward)/.48f*Mathf.Rad2Deg*Time.deltaTime;foreach(var wheel in wheels)wheel.Rotate(Vector3.up,spin,Space.Self);if(tails!=null){bool brake=Motor.Brake!=null&&Motor.Brake.Held;var mat=MeshArt.Mat(brake?"VanBraking":"VanTail",brake?new Color(1,.04f,.02f):new Color(.65f,.035f,.025f),-1,true);foreach(var r in tails)r.sharedMaterial=mat;}}
  static GameObject Loft(Transform parent,string name,float[] ys,float[] widths,float rear,float front,Material mat){var verts=new List<Vector3>();var tris=new List<int>();for(int j=0;j<ys.Length;j++){float x=widths[j],b=.12f;verts.AddRange(new[]{new Vector3(-x+b,ys[j],rear),new Vector3(x-b,ys[j],rear),new Vector3(x,ys[j],rear+b),new Vector3(x,ys[j],front-b),new Vector3(x-b,ys[j],front),new Vector3(-x+b,ys[j],front),new Vector3(-x,ys[j],front-b),new Vector3(-x,ys[j],rear+b)});}for(int j=0;j<ys.Length-1;j++)for(int i=0;i<8;i++){int a=j*8+i,b=j*8+(i+1)%8,c=a+8,d=b+8;tris.AddRange(new[]{a,c,b,b,c,d});}for(int i=1;i<7;i++){tris.AddRange(new[]{0,i,i+1});int top=(ys.Length-1)*8;tris.AddRange(new[]{top,top+i+1,top+i});}return MeshArt.Mesh(parent,name,verts.ToArray(),tris.ToArray(),null,mat);}
  public static void Text(Transform parent,string words,Vector3 position,float size,Color color,Quaternion rotation){var go=new GameObject(words,typeof(TextMesh));go.transform.SetParent(parent,false);go.transform.localPosition=position;go.transform.localRotation=rotation;var text=go.GetComponent<TextMesh>();text.text=words;text.characterSize=size/5f;text.fontSize=64;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.color=color;text.font=Resources.Load<Font>("Fonts/Barlow-Bold");if(text.font!=null)go.GetComponent<MeshRenderer>().sharedMaterial=text.font.material;}
  static void Gear(Transform root,float radius,Material orange,Material navy){var ring=MeshArt.Ring(root,"Gear",radius,.12f,0,orange,32);ring.transform.localRotation=Quaternion.Euler(90,0,0);for(int i=0;i<12;i++){float a=i*30*Mathf.Deg2Rad;var tooth=MeshArt.Box(root,"Gear tooth",new(Mathf.Cos(a)*radius,Mathf.Sin(a)*radius,0),new(.11f,.11f,.045f),orange);tooth.transform.localRotation=Quaternion.Euler(0,0,i*30);}var wrench=new GameObject("Wrench").transform;wrench.SetParent(root,false);wrench.localRotation=Quaternion.Euler(0,0,-34);MeshArt.Box(wrench,"Handle",new(0,-.02f,-.035f),new(.07f,.43f,.055f),navy);MeshArt.Oval(wrench,"Wrench head",new(0,.19f,-.035f),new(.18f,.18f,.055f),navy);MeshArt.Box(wrench,"Open jaw",new(0,.26f,-.08f),new(.075f,.09f,.015f),MeshArt.Mat("VanPearl",new(.95f,.96f,.94f)));}
